-- branch: A branch, service centre or virtual unit of a legal entity
CREATE TABLE branch (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  legal_entity_id              uuid NOT NULL REFERENCES legal_entity(id),
  code                         varchar(32) NOT NULL,
  name                         varchar(160) NOT NULL,
  branch_type                  varchar(40) NOT NULL DEFAULT 'BRANCH' CHECK (branch_type IN ('HEAD_OFFICE', 'BRANCH', 'SERVICE_CENTER', 'VIRTUAL', 'AGENT_HUB', 'BACK_OFFICE')),
  parent_id                    uuid REFERENCES branch(id),
  routing_code                 varchar(32),
  address_line1                varchar(255),
  address_line2                varchar(255),
  city                         varchar(120),
  region                       varchar(120),
  postal_code                  varchar(20),
  country                      char(2) NOT NULL,
  latitude                     numeric(18,10),
  longitude                    numeric(18,10),
  phone                        varchar(20),
  email                        varchar(320),
  opening_hours                jsonb,
  holiday_calendar_id          uuid,
  manager_user_id              uuid,
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'TEMPORARILY_CLOSED', 'CLOSED')),
  opened_on                    date,
  closed_on                    date,
  close_reason                 varchar(255),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_branch_code UNIQUE (tenant_id, code)
);
COMMENT ON TABLE branch IS 'A branch, service centre or virtual unit of a legal entity';
COMMENT ON COLUMN branch.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN branch.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN branch.created_at IS 'Creation time';
COMMENT ON COLUMN branch.created_by IS 'Principal that created the row';
COMMENT ON COLUMN branch.updated_at IS 'Last update time';
COMMENT ON COLUMN branch.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN branch.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN branch.legal_entity_id IS 'Owning legal entity';
COMMENT ON COLUMN branch.code IS 'Branch code';
COMMENT ON COLUMN branch.name IS 'Branch name';
COMMENT ON COLUMN branch.branch_type IS 'Kind of unit';
COMMENT ON COLUMN branch.parent_id IS 'Parent unit (region, head office)';
COMMENT ON COLUMN branch.routing_code IS 'Sort code / routing / IFSC code';
COMMENT ON COLUMN branch.address_line1 IS 'Address line 1';
COMMENT ON COLUMN branch.address_line2 IS 'Address line 2';
COMMENT ON COLUMN branch.city IS 'City';
COMMENT ON COLUMN branch.region IS 'State / province';
COMMENT ON COLUMN branch.postal_code IS 'Postal code';
COMMENT ON COLUMN branch.country IS 'Country';
COMMENT ON COLUMN branch.latitude IS 'Latitude';
COMMENT ON COLUMN branch.longitude IS 'Longitude';
COMMENT ON COLUMN branch.phone IS 'Branch phone';
COMMENT ON COLUMN branch.email IS 'Branch email';
COMMENT ON COLUMN branch.opening_hours IS 'Opening hours by weekday';
COMMENT ON COLUMN branch.holiday_calendar_id IS 'Holiday calendar';
COMMENT ON COLUMN branch.manager_user_id IS 'Branch manager';
COMMENT ON COLUMN branch.status IS 'Status';
COMMENT ON COLUMN branch.opened_on IS 'Opening date';
COMMENT ON COLUMN branch.closed_on IS 'Closing date (set by /close)';
COMMENT ON COLUMN branch.close_reason IS 'Reason given on /close';
COMMENT ON COLUMN branch.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN branch.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN branch.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
